#!/bin/sh
# ============================================================================
# roo_fix — ROOter 24.10 live-fixes installer (generated monolith)
#
# Applies four generic fixes to ROOter 24.10 boxes built from the same
# ./build ecosystem (the routers listed in router2410.json):
#   1. IPv6 end-to-end  (firewall _6 members + masq6, lan ip6*, wan6 PD,
#                        odhcpd RA, mwan3 numeric tracking, mwan3 v6
#                        conntrack-flush removal)
#   2. TTL/HL nft fix   (handlettl.sh broken nft syntax on fw4 builds)
#   3. Preserve fix     (skip AT writes / hard reset when the modem already
#                        owns the session; UI toggle for it)
#   4. mwan3 diag fix   (luci-mwan3 reported phantom "missing rule / table"
#                        for wan<N>_6 by always using IPv4-only ip commands;
#                        diagnostic-only, no routing behaviour change)
#   5. mwan3track fix   (tracker pinned one ipv6 source address while the
#                        carrier rotates the delegated /64, so every track
#                        target failed with "Address not available"; the
#                        patched tracker re-derives its source in place)
#
# 1 and 5 both require ACTIVATION: mwan3 is restarted (its reload_service is
# { stop; start; }, which does respawn trackers) when, and only when, this run
# actually changed mwan3 config or replaced the tracker binary.
#
# Self-contained: payloads are embedded base64 at build time by build.sh.
# POSIX sh / busybox-compatible — runs on the router itself.
#
# Usage:
#   sh install.sh [--check]             # --check = read-only audit
#   wget -qO- <url> | sh -s             # default: apply (pipe, NOT sh -c:
#   wget -qO- <url> | sh -s -- --check  # audit first)
#   NOTE: this script is ~150 KB and the kernel caps a single argv entry at
#   128 KiB, so `sh -c "$(curl …)"` fails with "Argument list too long" on
#   the router. Always pipe via stdin.
#
# Test-harness env (offline only, see tests/):
#   ROOTUP_ROOT=<dir>    operate on <dir> as the root filesystem (fake root)
#   ROOTUP_TEST=1        skip real-root checks and service restarts
#   ROOTUP_PROCFS=<dir>  procfs mount point to read for the IPv6 gate
#   ROOTUP_SKIP_NFT=1    skip live nft verification
# ============================================================================

VERSION="1.2.0"
ROOT="${ROOTUP_ROOT:-/}"
TESTMODE="${ROOTUP_TEST:-0}"
PROCFS="${ROOTUP_PROCFS:-/proc}"
SKIP_NFT="${ROOTUP_SKIP_NFT:-0}"

MODE="apply"
case "${1:-apply}" in
	--check|check)   MODE="check" ;;
	--apply|apply)   MODE="apply" ;;
	--help|-h)       cat >&2 <<'HELP'
roo_fix — ROOter 24.10 live-fixes installer
  --check   read-only audit: print what would change, write nothing
  --apply   apply the fixes with automatic backup + rollback script
  (default) --apply
HELP
		exit 0 ;;
	*)    echo "roo_fix: unknown argument '$1' (--check | --apply | --help)" >&2; exit 1 ;;
esac

TMPD=""
cleanup() { [ -n "$TMPD" ] && rm -rf "$TMPD" 2>/dev/null; }
trap cleanup EXIT HUP INT TERM
TMPD="$(mktemp -d /tmp/roofix.XXXXXX 2>/dev/null)"
if [ -z "$TMPD" ] || [ ! -d "$TMPD" ]; then
	TMPD="/tmp/roofix.$$"
	mkdir -p "$TMPD" 2>/dev/null || {
		printf 'FATAL: cannot create temp dir %s\n' "$TMPD" >&2
		exit 1
	}
fi

CHANGED=0
# ---------------------------------------------------------------------------
# Common helpers (POSIX sh / busybox-safe)
# ---------------------------------------------------------------------------

# rootpath PATH -> full path under the active root (real / or fake root)
rp() { printf '%s' "$ROOT$1"; }

ok()   { printf '  [ OK ] %s\n' "$*"; }
warn() { printf '  [WARN] %s\n' "$*"; }
fail() { printf '  [FAIL] %s\n' "$*"; }
die()  { printf 'FATAL: %s\n' "$*" >&2; exit 1; }

# uci wrapper: plain `uci` on the box; test harness injects a stub via PATH.
uciq() { uci -q "$@"; }

# md5 of a file under the active root ("" if absent)
fmd5() {
	[ -f "$(rp "$1")" ] || { printf ''; return; }
	md5sum "$(rp "$1")" | cut -d' ' -f1
}

# service wrapper (no-op in test mode / for missing init scripts)
svc() {
	[ "$TESTMODE" = 1 ] && { debug "svc(skip) $1 $2"; return 0; }
	s="$1" a="$2"
	if [ -x "/etc/init.d/$s" ]; then
		"/etc/init.d/$s" "$a" 2>/dev/null
	else
		debug "svc(missing) /etc/init.d/$s"
	fi
}

debug() { [ "${ROOTUP_DEBUG:-0}" = 1 ] && printf '  [ dbg ] %s\n' "$*" >&2; }

note() { printf '  [NOTE] %s\n' "$*"; }

# has_cmd CMD  -> 0 if a command exists (respects a PATH that includes stubs)
has_cmd() { command -v "$1" >/dev/null 2>&1; }

# ------------------------------------------------------------------ decode ----
# b64dec — base64 decode stdin -> stdout. Pure awk, busybox-safe: ROOter 24.10
# images have NO `base64` binary (probed live: not in PATH, not a busybox
# applet), so GNU `base64 -d` is a hard no-go on the target. awk is
# guaranteed (busybox). LC_ALL=C is forced so printf "%c" emits raw bytes
# for values >= 128 (payloads are text; md5-gating still requires byte
# exactness). Output is then md5-verified against the canonical fingerprint.
b64dec() {
	LC_ALL=C awk '
		function val(c,    i) {
			i = index("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", c)
			return i ? i - 1 : 0
		}
		{
			s = $0
			n = length(s)
			for (i = 1; i <= n; i += 4) {
				c1 = substr(s, i, 1)
				c2 = substr(s, i + 1, 1)
				c3 = substr(s, i + 2, 1)
				c4 = substr(s, i + 3, 1)
				v = val(c1) * 262144 + val(c2) * 4096
				if (c3 != "" && c3 != "=") v += val(c3) * 64
				if (c4 != "" && c4 != "=") v += val(c4)
				printf "%c", int(v / 65536)
				if (c3 != "" && c3 != "=") printf "%c", int((v % 65536) / 256)
				if (c4 != "" && c4 != "=") printf "%c", v % 256
			}
		}' 2>/dev/null || return 1
	return 0
}

# ---------------------------------------------------------------- backup ----
BK=""
BK_FILES=""
make_backup() {
	ts=""
	[ "$MODE" = "check" ] && return 0
	ts="$(date +%Y%m%d-%H%M%S)"
	BK="$(rp /root)/rooter-upgrade-bk-$ts"
	mkdir -p "$BK/files" || die "cannot create backup dir $BK"
	BK_FILES="$BK/files"
	if has_cmd uci; then
		for p in network firewall dhcp mwan3 profile; do
			uci -q export "$p" > "$BK/$p.uci" 2>/dev/null || rm -f "$BK/$p.uci"
		done
	fi
	note "backup dir: $BK"
}

# back up one file (as it exists now) before we replace it
backup_file() { # dest-path (absolute, no leading /)
	dest="$1" rel=""
	[ "$MODE" = "apply" ] || return 0
	[ -n "$BK_FILES" ] || return 0
	rel="$(printf '%s' "$dest" | tr '/' '_')"
	if [ -f "$(rp "$dest")" ]; then
		cp -p "$(rp "$dest")" "$BK_FILES/$rel" 2>/dev/null || { warn "backup copy failed: $dest"; return 0; }
		# manifest: backup-name<space>dest-path — the filesystem name alone is
		# NOT reversible (underscores in filenames corrupt tr '_' '/'), so
		# record the real destination explicitly (see write_rollback). A space
		# delimiter is safe here (no path has spaces) and, unlike a tab via
		# printf, survives the unquoted heredoc without backslash mangling.
		printf '%s %s\n' "$rel" "$dest" >> "$BK/manifest"
	fi
}

write_rollback() {
	[ "$MODE" = "check" ] && return 0
	cat > "$BK/rollback.sh" <<EOF
#!/bin/sh
# Restore state captured before running roo_fix on $(date).
# Sourced by the operator if the fixes must be reverted.
# Set ROOT_PREFIX=<dir> to restore under <dir> instead of / (test/dry-run).
set -e
BK="$BK"
R="\${ROOT_PREFIX:-}"
if [ -s "\$BK/manifest" ]; then
  while read -r rel dest || [ -n "\$rel" ]; do
    [ -f "\$BK/files/\$rel" ] || continue
    echo "restore: \$R/\$dest"
    cp -p "\$BK/files/\$rel" "\$R/\$dest"
  done < "\$BK/manifest"
else
  for f in \$(ls "\$BK/files"); do
    dest="\$(printf '%s' "\$f" | tr '_' '/')"
    [ -f "\$BK/files/\$f" ] || continue
    echo "restore: \$R/\$dest"
    cp -p "\$BK/files/\$f" "\$R/\$dest"
  done
fi
for p in network firewall dhcp mwan3 profile; do
  [ -f "\$BK/\$p.uci" ] && { echo "uci import \$p"; uci import "\$p" < "\$BK/\$p.uci" 2>/dev/null; }
done
echo "Restart services to apply reverted config (network, firewall, odhcpd, mwan3)."
EOF
	chmod +x "$BK/rollback.sh"
	note "rollback: sh $BK/rollback.sh"
}
# ---------------------------------------------------------------------------
# Environment detection
# ---------------------------------------------------------------------------

# run_checks: verify we are on a supported ROOter 24.10 box (or a test root)
run_checks() {
	[ "$TESTMODE" = 1 ] && { debug "test mode: skipping live env checks"; env_probe; return 0; }

	[ "$(id -u)" = 0 ] || die "must run as root (uid 0) on the router"

	[ -f /etc/openwrt_release ] || die "not an OpenWrt box (/etc/openwrt_release missing)"

	. /etc/openwrt_release

	# 24.10-based only (the TTL nft fix and the preserve/IPv6 fixes are
	# validated on the OpenWrt 24.10 / firewall4 / nftables line).
	case "$DISTRIB_RELEASE" in
		24.*) : ;;
		*) die "unsupported base OpenWrt '$DISTRIB_RELEASE' — this installer targets 24.10 only" ;;
	esac

	[ -d /usr/lib/rooter/connect ] || die "ROOter not detected (/usr/lib/rooter/connect missing)"
	[ -f /usr/lib/rooter/connect/handlettl.sh ] || warn "handlettl.sh not found — TTL fix will no-op"

	# fw4 / nftables needed for the TTL fix (legacy iptables builds unaffected)
	if has_cmd nft; then
		NFT_OK=1
	else
		NFT_OK=0
		warn "nftables (nft) not found — TTL/HL fix skipped (iptables-era build unaffected)"
	fi

	env_probe
}

# modem_iface N -> interface name of modem N ("" if none)
modem_iface() { uciq get modem.modem$1.interface; }

# env_probe: resolve per-box values used by the fixes (modems, zones,
# fw4/nft + kernel IPv6 probing — real AND test mode)
env_probe() {
	# kernel ipv6 device
	if [ -e "$PROCFS/sys/net/ipv6" ]; then
		IPV6_OK=1
	else
		IPV6_OK=0
		warn "kernel IPv6 not visible ($PROCFS/sys/net/ipv6 missing) — IPv6 fix skipped"
	fi

	MODEMS=""            # space-separated modem indices with an interface
	i=1
	while [ "$i" -le 5 ]; do
		iface="$(modem_iface "$i")"
		if [ -n "$iface" ]; then
			MODEMS="$MODEMS $i"
		fi
		i=$((i+1))
	done
	WAN_ZONE=""          # firewall zone section named 'wan'
	z=0
	while :; do
		zn="$(uciq get firewall.@zone[$z].name)"
		[ -z "$zn" ] && break
		if [ "$zn" = "wan" ]; then WAN_ZONE="$z"; break; fi
		z=$((z+1))
	done
	[ -z "$WAN_ZONE" ] && warn "no firewall zone named 'wan' found — IPv6 firewall members/masq6 not applied"
}
# embedded payload table — generated by build.sh, do not edit
ROOTUP_TABLE="\
create_hostless.sh|/usr/lib/rooter/connect/create_hostless.sh|0755|47c26fbece1206a8791759aaab1a1825|88107b5795c1f0064868cbf2aa128546|0|
handlettl.sh|/usr/lib/rooter/connect/handlettl.sh|0755|4618c693588b30dfb6e0ba2e5af9970b|9a9a287a44bfda16a394e19b4259bf1d|0|
get_profile.sh|/usr/lib/rooter/connect/get_profile.sh|0755|43889f4a5d1323f66f9cf32d3ba74955|96140f59ad8792d348aa1890c829ea8d|0|
profiles.lua|/usr/lib/lua/luci/model/cbi/rooter/profiles.lua|0644|61d7dc181b0c4c478b105c78fbd73064|babb8bc4deaee0aa031f535b1439c442|0|
restartrun.sh|/usr/lib/rooter/luci/restartrun.sh|0755|a5cec9111a57ff4a3e8d7a3f04ae9527||0|
luci-mwan3|/usr/libexec/luci-mwan3|0755|988f3573a99baadaed966b04517b4613|966e6edc692967da0570b5cb9512ec9b|0|
mwan3track|/usr/sbin/mwan3track|0755|c42c9e279674b563edb208188f8cfd91|4c5960015068a7265ea6bdec61fea369,a7e45861316f0801f5e914055048bf74,89888f33b73466f82d01dee1109fa296|0|
